// Transaction History page
// Shows ALL transactions of the logged-in user
// User can Edit or Delete any transaction from here

import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Navbar from '../components/Navbar';
import './TransactionHistory.css';

function TransactionHistory() {
  const [transactions, setTransactions] = useState([]);
  const [editingId, setEditingId] = useState(null);  // which transaction is being edited
  const [editData, setEditData] = useState({});       // holds the form values while editing
  const [message, setMessage] = useState('');

  const token = localStorage.getItem('token');

  // Load all transactions when page opens
  useEffect(() => {
    fetchTransactions();
  }, []);

  const fetchTransactions = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/transactions', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setTransactions(response.data);
    } catch (error) {
      console.log('Error fetching transactions:', error.message);
    }
  };

  // When user clicks Edit button, we store that transaction's data in editData
  const handleEditClick = (transaction) => {
    setEditingId(transaction.id);
    setEditData({
      title: transaction.title,
      amount: transaction.amount,
      category: transaction.category,
      type: transaction.type,
      date: transaction.date
    });
    setMessage('');
  };

  // When user types in the edit form, update editData
  const handleEditChange = (e) => {
    setEditData({ ...editData, [e.target.name]: e.target.value });
  };

  // When user clicks Save, send PUT request to backend
  const handleSave = async (id) => {
    try {
      await axios.put(
        `http://localhost:5000/api/transactions/${id}`,
        editData,
        { headers: { Authorization: `Bearer ${token}` } }
      );

      setMessage('Transaction updated successfully!');
      setEditingId(null);  // close the edit form
      fetchTransactions(); // refresh the list

    } catch (error) {
      setMessage('Could not update transaction. Please try again.');
      console.log('Update error:', error.message);
    }
  };

  // Cancel editing without saving
  const handleCancel = () => {
    setEditingId(null);
    setEditData({});
    setMessage('');
  };

  // Delete a transaction
  const handleDelete = async (id) => {
    try {
      await axios.delete(`http://localhost:5000/api/transactions/${id}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setTransactions(transactions.filter(t => t.id !== id));
      setMessage('Transaction deleted.');
    } catch (error) {
      console.log('Delete error:', error.message);
    }
  };

  return (
    <div>
      <Navbar />
      <div className="history-container">

        <h2 className="history-heading">Transaction History</h2>
        <p className="history-subtext">View, edit, or delete all your transactions</p>

        {/* Show success/error message */}
        {message && <p className="history-message">{message}</p>}

        {transactions.length === 0 ? (
          <p className="no-data">No transactions found. Add some from the Dashboard.</p>
        ) : (
          <table className="history-table">
            <thead>
              <tr>
                <th>Title</th>
                <th>Amount (₹)</th>
                <th>Category</th>
                <th>Type</th>
                <th>Date</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {transactions.map((t) => (
                <tr key={t.id}>

                  {/* If this row is being edited, show input fields */}
                  {editingId === t.id ? (
                    <>
                      <td>
                        <input
                          type="text"
                          name="title"
                          value={editData.title}
                          onChange={handleEditChange}
                          className="edit-input"
                        />
                      </td>
                      <td>
                        <input
                          type="number"
                          name="amount"
                          value={editData.amount}
                          onChange={handleEditChange}
                          className="edit-input"
                        />
                      </td>
                      <td>
                        <input
                          type="text"
                          name="category"
                          value={editData.category}
                          onChange={handleEditChange}
                          className="edit-input"
                        />
                      </td>
                      <td>
                        <select
                          name="type"
                          value={editData.type}
                          onChange={handleEditChange}
                          className="edit-input"
                        >
                          <option value="income">income</option>
                          <option value="expense">expense</option>
                        </select>
                      </td>
                      <td>
                        <input
                          type="date"
                          name="date"
                          value={editData.date}
                          onChange={handleEditChange}
                          className="edit-input"
                        />
                      </td>
                      <td>
                        <button className="save-btn" onClick={() => handleSave(t.id)}>Save</button>
                        <button className="cancel-btn" onClick={handleCancel}>Cancel</button>
                      </td>
                    </>
                  ) : (
                    // Normal view (not editing)
                    <>
                      <td>{t.title}</td>
                      <td>₹ {parseFloat(t.amount).toFixed(2)}</td>
                      <td>{t.category}</td>
                      <td>
                        <span className={t.type === 'income' ? 'badge income' : 'badge expense'}>
                          {t.type}
                        </span>
                      </td>
                      <td>{t.date}</td>
                      <td>
                        <button className="edit-btn" onClick={() => handleEditClick(t)}>Edit</button>
                        <button className="delete-btn" onClick={() => handleDelete(t.id)}>Delete</button>
                      </td>
                    </>
                  )}

                </tr>
              ))}
            </tbody>
          </table>
        )}

      </div>
    </div>
  );
}

export default TransactionHistory;
